package studyfix.assignment.service;
import studyfix.Identity;
import studyfix.StudyFixGateway;
import studyfix.assignment.model.Exercise;
import studyfix.assignment.model.GradingResult;
import studyfix.assignment.persistence.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.sql.SQLException;
import static studyfix.assignment.protocol.AssignmentJson.*;

/** All recipient permissions come from durable enrollment, never the current room. */
public final class WeekAssignmentService {
 public interface Enqueue{boolean offer(String id);}
 public final WeekAssignmentRepository repository;
 private final AssignmentRepository repo;private final StudyFixGateway gateway;private final Enqueue queue;
 public WeekAssignmentService(AssignmentRepository repo,StudyFixGateway gateway,Enqueue queue)throws SQLException{this.repo=repo;this.gateway=gateway;this.queue=queue;repository=new WeekAssignmentRepository(repo);}
 private static void teacher(Identity who){if(who.role()!=Identity.Role.TEACHER)throw new SecurityException("Chỉ giảng viên được giao và quản lý bài.");}
 private static List<Map<String,Object>> maps(Object value){return list(value).stream().map(v->map(v)).toList();}
 private static List<String> ids(Object value,int max){if(!(value instanceof List<?>))throw new IllegalArgumentException("Danh sách lựa chọn không hợp lệ.");List<String> ids=list(value).stream().map(String::valueOf).toList();if(ids.size()>max||new HashSet<>(ids).size()!=ids.size()||ids.stream().anyMatch(v->v.isBlank()||v.length()>160))throw new IllegalArgumentException("Lựa chọn trùng hoặc vượt giới hạn.");return ids;}
 private static long deadline(Map<String,Object> req){Object raw=req.getOrDefault("deadlineAt",0);if(!(raw instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=n.longValue())throw new IllegalArgumentException("Hạn nộp phải là thời điểm hợp lệ.");long value=number(req,"deadlineAt",0),now=System.currentTimeMillis();if(value!=0&&(value<=now||value>now+365L*24*60*60000))throw new IllegalArgumentException("Hạn nộp phải ở tương lai, tối đa 1 năm; 0 là không giới hạn.");return value;}
 private Map<String,Object> authorized(Identity who,String work,String user)throws SQLException{
  var row=repository.work(work,who.role()==Identity.Role.STUDENT?who.userId():user);var dir=gateway.weekDirectory(who);var stored=maps(parse(text(row,"classesJson","[]")));boolean allowed;
  if(who.role()==Identity.Role.STUDENT)allowed=maps(dir.get("classes")).stream().anyMatch(c->text(row,"ownerId","").equals(c.get("ownerId"))&&stored.stream().anyMatch(s->s.get("id").equals(c.get("id"))));
  else allowed=who.userId().equals(row.get("ownerId"))&&maps(dir.get("students")).stream().anyMatch(s->user.equals(s.get("id"))&&stored.stream().anyMatch(c->c.get("id").equals(s.get("classId"))));
  if(!allowed)throw new SecurityException("Bài giao không thuộc lớp/sinh viên bạn đang quản lý hoặc đang theo học.");return row;
 }
 public Map<String,Object> handle(Map<String,Object> req,Identity who)throws Exception{
  String type=text(req,"type","");Map<String,Object> result;
  switch(type){
   case "WA_SOURCES"->{teacher(who);result=gateway.weekDirectory(who);}
   case "WA_TIMELINE"->{var dir=gateway.weekDirectory(who);var classes=maps(dir.get("classes"));String classId=text(req,"classId","");if(classId.isEmpty()&&!classes.isEmpty())classId=text(classes.getFirst(),"id","");String selected=classId;var chosen=classes.stream().filter(c->selected.equals(c.get("id"))).findFirst().orElse(null);if(!classId.isEmpty()&&chosen==null)throw new SecurityException("Lớp không thuộc phạm vi của bạn.");List<Map<String,Object>> items=who.role()==Identity.Role.STUDENT&&chosen!=null?repository.studentWork(who,classId).stream().filter(w->Objects.equals(w.get("ownerId"),chosen.get("ownerId"))).toList():List.of();var weeks=new ArrayList<>(repository.timelineWeeks());if(who.role()==Identity.Role.TEACHER)for(var old:repository.archivedWeeks(who)){old.put("archived",true);old.put("exerciseIds",List.of());old.put("exerciseCount",0);old.put("isMine",false);weeks.add(old);}Set<Object> frozen=new HashSet<>();for(var work:items){if(frozen.add(work.get("weekId")))for(var existing:weeks)if(existing.get("id").equals(work.get("weekId"))){existing.put("title",work.get("weekTitle"));existing.put("weekNo",work.get("weekNo"));}}for(var work:items)if(weeks.stream().noneMatch(w->w.get("id").equals(work.get("weekId"))))weeks.add(mapOf("id",work.get("weekId"),"weekNo",work.get("weekNo"),"title",work.get("weekTitle"),"description","Week đã giao, được giữ lại sau khi gỡ khỏi ngân hàng.","archived",true));weeks.sort(Comparator.comparingLong(w->number(w,"weekNo",0)));result=mapOf("classes",classes,"classId",classId,"weeks",weeks,"work",items);}
   case "WA_CREATE"->{teacher(who);var dir=gateway.weekDirectory(who);List<String> classes=ids(req.get("classIds"),100),questions=ids(req.get("exerciseIds"),100),students=ids(req.getOrDefault("studentIds",List.of()),2500);String audience=text(req,"audience","CLASSES");if(!Set.of("CLASSES","STUDENTS").contains(audience)||classes.isEmpty()||questions.isEmpty()||audience.equals("STUDENTS")&&students.isEmpty())throw new IllegalArgumentException("Chọn lớp, bài tập và người nhận hợp lệ.");Set<String> available=new HashSet<>();for(var c:maps(dir.get("classes")))if(!Boolean.TRUE.equals(c.get("closed")))available.add(text(c,"id",""));if(!available.containsAll(classes))throw new SecurityException("Chỉ giao cho lớp đang mở do bạn quản lý.");
    Map<String,Map<String,Object>> receivers=new LinkedHashMap<>();for(var user:maps(dir.get("students")))if(classes.contains(user.get("classId"))&&(audience.equals("CLASSES")||students.contains(user.get("id")))){String id=text(user,"id","");var target=receivers.computeIfAbsent(id,k->{var copy=new LinkedHashMap<>(user);copy.put("classes",new ArrayList<Map<String,Object>>());return copy;});@SuppressWarnings("unchecked") var list=(List<Map<String,Object>>)target.get("classes");list.add(mapOf("id",user.get("classId"),"code",user.get("classCode"),"name",user.get("className")));}
    if(receivers.isEmpty()||receivers.size()>2500||(long)receivers.size()*questions.size()>10000)throw new IllegalArgumentException("Chọn người nhận; tối đa 2500 sinh viên và 10000 lượt giao bài mỗi lần.");if(audience.equals("STUDENTS")&&!receivers.keySet().containsAll(students))throw new SecurityException("Có sinh viên không thuộc lớp đã chọn hoặc không còn được bạn quản lý.");String key=text(req,"requestKey","");if(!key.matches("[A-Za-z0-9_-]{8,100}"))throw new IllegalArgumentException("Thiếu mã yêu cầu giao bài.");long due=deadline(req);String week=text(req,"weekId","");String hash=ProblemBuilderRepository.hash(mapOf("weekId",week,"classIds",classes.stream().sorted().toList(),"studentIds",students.stream().sorted().toList(),"audience",audience,"exerciseIds",questions,"deadlineAt",due));result=repository.create(who,week,questions,new ArrayList<>(receivers.values()),due,key,hash);
   }
   case "WA_PROGRESS"->{teacher(who);var dir=gateway.weekDirectory(who);String classId=text(req,"classId","");if(!classId.isEmpty()&&maps(dir.get("classes")).stream().noneMatch(c->classId.equals(c.get("id"))))throw new SecurityException("Lớp không thuộc bạn.");Set<String> users=new HashSet<>();for(var u:maps(dir.get("students")))if(classId.isEmpty()||classId.equals(u.get("classId")))users.add(text(u,"id",""));result=mapOf("classes",dir.get("classes"),"items",repository.teacherProgress(who,text(req,"weekId",""),classId,users));}
   case "WA_CONTROL"->{teacher(who);String id=text(req,"dispatchId","");Set<String> owned=new HashSet<>();for(var c:maps(gateway.weekDirectory(who).get("classes")))owned.add(text(c,"id",""));if(!owned.containsAll(repository.dispatchClasses(who,id)))throw new SecurityException("Đợt giao có lớp không còn thuộc quyền quản lý.");var old=repository.dispatch(who,id);String action=text(req,"action","");if(!Set.of("EXTEND","CLOSE","OPEN").contains(action))throw new IllegalArgumentException("Thao tác không hợp lệ.");long due=action.equals("EXTEND")?deadline(req):number(old,"deadline_at",0);if(action.equals("EXTEND")&&due>0&&due<=number(old,"deadline_at",0))throw new IllegalArgumentException("Hạn gia hạn phải sau hạn hiện tại, hoặc chọn không giới hạn.");if(action.equals("OPEN")&&due>0&&due<=System.currentTimeMillis())throw new IllegalArgumentException("Gia hạn trước khi mở lại bài đã quá hạn.");repository.control(who,id,integer(req,"expectedRevision",0),action,due);result=mapOf("saved",true);}
   case "WA_OPEN"->{if(who.role()!=Identity.Role.STUDENT)throw new SecurityException("Chỉ sinh viên làm bài được giao.");var work=authorized(who,text(req,"workId",""),"");Exercise e=repo.getExercise(text(work,"exerciseId",""));var exercise=new LinkedHashMap<>(e.publicView());exercise.remove("hints");exercise.put("publicTests",e.tests().stream().filter(t->!t.hidden()).map(t->mapOf("input",t.input(),"expectedOutput",t.expected())).toList());result=mapOf("work",work,"exercise",exercise,"history",repository.history(text(work,"workId",""),who.userId()));}
   case "WA_SUBMIT","WA_RUN"->{if(who.role()!=Identity.Role.STUDENT)throw new SecurityException("Chỉ sinh viên được nộp bài.");String work=text(req,"workId","");authorized(who,work,"");String source=text(req,"sourceCode","");if(source.isBlank()||source.getBytes(StandardCharsets.UTF_8).length>32768)throw new IllegalArgumentException("Code cần từ 1 byte đến 32 KiB.");String key=text(req,"requestKey","");if(!key.matches("[A-Za-z0-9_-]{8,100}"))throw new IllegalArgumentException("Thiếu mã yêu cầu nộp bài.");var receipt=repository.submit(who,work,key,source,type.equals("WA_RUN"));String id=text(receipt,"id","");if(Boolean.TRUE.equals(receipt.get("created"))&&!queue.offer(id))repository.finish(id,new GradingResult("INTERNAL_ERROR",0,100,0,0,"Đã lưu bài nhưng hàng đợi chấm đầy; thử lại sau.",0,List.of()));result=mapOf("submission",publicResult(repository.result(id)),"reused",!Boolean.TRUE.equals(receipt.get("created")));}
   case "WA_RESULT"->{String id=text(req,"submissionId","");var raw=repository.rawSubmission(id);if(who.role()==Identity.Role.STUDENT&&!who.userId().equals(raw.get("user_id")))throw new SecurityException("Chỉ xem bài nộp của mình.");authorized(who,text(raw,"work_id",""),text(raw,"user_id",""));result=mapOf("submission",publicResult(repository.result(id)));}
   case "WA_HISTORY"->{String user=who.role()==Identity.Role.STUDENT?who.userId():text(req,"studentId","");authorized(who,text(req,"workId",""),user);result=mapOf("submissions",repository.history(text(req,"workId",""),user));}
   default->throw new IllegalArgumentException("Thao tác giao bài Week không hợp lệ.");
  }
  return mapOf("status","OK","data",result,"requestId",text(req,"requestId",""));
 }
 private static Map<String,Object> publicResult(Map<String,Object> row){row.remove("userId");row.put("testResults",maps(row.get("testResults")).stream().filter(t->!Boolean.TRUE.equals(t.get("hidden"))).toList());return row;}
}
